mapper.update:
UPDATE cw_dead_letter
SET `status` = 'PROCESSING', lease_owner = #{owner}, lease_until_ms = #{leaseUntilMs}
WHERE id = #{id}
  AND ((`status` = 'PENDING' AND next_retry_at_ms <= #{nowMs})
    OR (`status` = 'PROCESSING' AND lease_until_ms <= #{nowMs}))

mapper.select:
SELECT  FROM cw_dead_letter
WHERE `status` = 'PROCESSING' AND lease_owner = #{owner} AND lease_until_ms = #{leaseUntilMs}
ORDER BY next_retry_at_ms

mapper.update:
UPDATE cw_dead_letter
SET `status` = #{record.status}, attempts = #{record.attempts}, last_error = #{record.lastError},
    next_retry_at_ms = #{record.nextRetryAtMs}, lease_owner = #{record.leaseOwner},
    lease_until_ms = #{record.leaseUntilMs}, finished_at_ms = #{record.finishedAtMs}
WHERE id = #{record.id} AND `status` = 'PROCESSING' AND lease_owner = #{owner}

mapper.select:
SELECT  FROM cw_dead_letter
WHERE `status` = #{status}
ORDER BY created_at_ms DESC
LIMIT #{limit}
